import json,glob
from collections import Counter
budget_tasks=[]
for f in sorted(glob.glob('*.result.json')):
  d=json.load(open(f))
  if d.get('agent',{}).get('exit_reason')=='budget_exceeded':
    budget_tasks.append(d['task_id'])
print('budget_exceeded tasks:',len(budget_tasks))
# analyze each for max identical consecutive tool call repeats
for tid in budget_tasks:
  try:
    msgs=json.load(open(tid+'.messages.json'))
  except: 
    print(tid,'no msgs'); continue
  # build sequence of tool call fingerprints
  fps=[]
  for m in msgs:
    if m.get('role')=='assistant':
      for tc in (m.get('tool_calls') or []):
        fps.append(tc['function']['name']+'|'+tc['function']['arguments'])
  # max consecutive identical
  maxrun=0; cur=1
  for i in range(1,len(fps)):
    if fps[i]==fps[i-1]: cur+=1; maxrun=max(maxrun,cur)
    else: cur=1
  if fps: maxrun=max(maxrun,1)
  # also count distinct fraction
  distinct=len(set(fps))
  print(tid,'ncalls',len(fps),'distinct',distinct,'max_identical_consec',maxrun)
"

